  `priority` int NOT NULL DEFAULT '1' COMMENT '우선도. 높을수록 우선순위가 높음',
  PRIMARY KEY (`admin_permission_idx`),
  UNIQUE KEY `uq_ap_user_permission` (`user_idx`,`permission_code`),
