	(97, '4e6aaf56-8fd1-46f9-a629-9f43dae0ff58', 'SPOT', 26, 'name', '도쿄 디즈니랜드', '12992e6a22cd9b3a8de6fdfe33879e5c9069df2fd803d3fde61f9973aba51394', 'ja', '東京ディズニーランド', 'google-cloud-translation-v2', '2026-04-16 07:41:26', '2026-04-16 07:41:26'),
